 const sellerFields=$('seller-form').elements;
 const validateBuilding=()=>{const value=sellerFields.building.value.trim(),number=Number(digits(value)),district=sellerFields.district.value;const invalid=value&&(!Number.isInteger(number)||number<1||district==='other'||district==='yasmin'&&number>333||district==='narges'&&number>291);sellerFields.building.setCustomValidity(invalid?'راجع رقم العمارة أو سيبه فاضي لو خارج النرجس والياسمين.':'');};
 sellerFields.building.addEventListener('input',validateBuilding);sellerFields.district.addEventListener('change',validateBuilding);validateBuilding();
